-- Generated by generate_spells.py from ability_tunables.csv; never hand-edit.
CREATE TABLE IF NOT EXISTS dc_ability_tuning (name VARCHAR(80) PRIMARY KEY, tuned_value DOUBLE NOT NULL, status VARCHAR(20) NOT NULL, notes TEXT NOT NULL);
